insert into public.jobs (slug, title, summary, location, employment, published) values
  ('AISolutionsArchitect', 'AI Solutions Architect', 'Sit at the intersection of sales, engineering, and delivery. You''ll lead technical pre-sales conversations, design enterprise AI architectures, and own delivery leadership across complex, multi-stakeholder engagements.', 'Hybrid', 'Full-time', true),
  ('AIStrategyConsultant', 'AI Strategy Consultant', 'Help enterprise leaders navigate AI transformation. Build AI roadmaps, quantify ROI, and sit in boardrooms helping C-suites make confident decisions about where and how to deploy AI. You''re the bridge between ambition and execution.', 'Hybrid', 'Full-time', true),
  ('DataEngineer', 'Data Engineer', 'Build the data infrastructure that powers enterprise AI. From real-time streaming pipelines to vector databases serving LLMs, you''ll be the foundation on which AI systems are built — at enterprise scale.', 'Remote', 'Full-time', true),
  ('FDEEngagementLead', 'FDE Engagement Lead', 'The most senior delivery role at Innovsol. Lead FDE teams inside enterprise clients — setting technical direction, managing stakeholders at C-suite level, and ensuring every 12-week sprint delivers measurable, production AI outcomes.', 'Hybrid', 'Full-time', true),
  ('MachineLearningEngineer', 'Machine Learning Engineer', 'Build and ship ML models that solve real enterprise problems — from NLP classification systems to time-series forecasting at scale. You''ll work within client teams, own model development end-to-end, and ensure production reliability.', 'Remote', 'Full-time', true),
  ('SeniorAiEngineer', 'Senior AI Engineer', 'As a Senior AI Engineer, you will design and build scalable AI solutions, LLM applications and intelligent agents that solve complex business problems. You will work closely with clients, architects and cross-functional teams to deliver impact at scale.', 'Remote / Hybrid / Gurgaon', 'Full-Time', true)
